class Solution {
  public int minValidStrings(String[] words, String target) {
    int n = target.length();
    int[] reach = new int[n];
    for (String w : words) {
      int m = w.length();
      char[] s = new char[m + 1 + n];
      w.getChars(0, m, s, 0);
      s[m] = '{';
      target.getChars(0, n, s, m + 1);
      int[] z = new int[s.length];
      for (int i = 1, l = 0, r = 0; i < s.length; i++) {
        if (i < r) z[i] = Math.min(r - i, z[i - l]);
        while (i + z[i] < s.length && s[z[i]] == s[i + z[i]]) z[i]++;
        if (i + z[i] > r) {
          l = i;
          r = i + z[i];
        }
      }
      for (int i = 0; i < n; i++) reach[i] = Math.max(reach[i], z[m + 1 + i]);
    }
    int end = 0, far = 0, jumps = 0;
    for (int i = 0; i < n; i++) {
      far = Math.max(far, i + reach[i]);
      if (i == end) {
        if (far <= i) return -1;
        jumps++;
        end = far;
        if (end >= n) return jumps;
      }
    }
    return -1;
  }
}
